const ApplicationDetailView = ({ app, comms, onDraftClick, onLogClick, onBack }) => {
  const [analysis, setAnalysis] = useState(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const runAnalysis = async () => {
    setIsAnalyzing(true);
    const result = await analyzeRisk(app, comms);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  useEffect(() => {
    if (!analysis && app.ghosting_risk_score > 50) {
      runAnalysis();
    }
  }, [app.id]);

  const appComms = comms.filter(c => c.application_id === app.id).sort((a, b) => new Date(b.date) - new Date(a.date));

  return (
    <motion.div 
      className="screen-container detail-view"
      initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
    >
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom: '24px' }}>
        ← Back to Dashboard
      </button>

      <div className="detail-header-area">
        <div>
          <h1 className="display-font" style={{ fontSize: '48px', margin: '0 0 8px 0' }}>{app.company_name}</h1>
          <div className="quote-font" style={{ color: 'var(--text-secondary)' }}>{app.role_title}</div>
        </div>
        <div className="action-group">
          <button className="btn-secondary" onClick={onLogClick}>Log Communication</button>
          <button className="btn-primary" onClick={onDraftClick}>Draft Follow-up</button>
        </div>
      </div>

      <div className="detail-grid">
        <div className="main-column">
          <h3 className="label-font" style={{ marginBottom: '16px', textTransform: 'uppercase', letterSpacing: '1px' }}>Timeline</h3>
          <div className="timeline">
            {appComms.map((comm, i) => (
              <motion.div 
                key={comm.id} className="timeline-node"
                initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.1 }}
              >
                <div className="node-dot" />
                <div className="node-content">
                  <div className="node-meta data-font">{comm.date} • {comm.sender_type}</div>
                  <div className="node-text body-font">{comm.raw_text}</div>
                  {comm.ai_intent && (
                    <div className="node-ai-insight">
                      <lucide.Sparkles size={14} style={{ color: 'var(--nu-red)' }} />
                      <span className="body-font" style={{ fontSize: '13px' }}>Intent: {comm.ai_intent}</span>
                    </div>
                  )}
                </div>
              </motion.div>
            ))}
          </div>
        </div>

        <div className="side-column">
          <div className="health-widget card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '24px' }}>
              <h3 className="label-font">Application Health</h3>
              <button className="btn-ghost" style={{ padding: '4px 8px', fontSize: '12px' }} onClick={runAnalysis} disabled={isAnalyzing} aria-label="Refresh Analysis">
                <lucide.RefreshCw size={14} className={isAnalyzing ? 'spin' : ''} />
              </button>
            </div>

            <GhostingRiskIndicator 
              score={analysis?.ghosting_risk_score || app.ghosting_risk_score} 
              status={analysis?.status_health || app.status_health}
              isLoading={isAnalyzing} 
              daysSinceContact={app.days_since_contact}
            />

            <div className="ai-sentiment-box" style={{ marginTop: '24px' }}>
              <div className="label-font" style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
                <lucide.BrainCircuit size={16} color="var(--nu-red)" />
