  }, []);

  const handleSelectApp = (id) => {
    setSelectedAppId(id);
    setCurrentScreen('application_detail_view');
  };

  const handleGenerateDrafts = (strategy) => {
    setDraftStrategy(strategy);
    setCurrentScreen('draft_comparison_view');
  };

  const handleCopyDraft = (draft) => {
    setApplications(apps => apps.map(a => a.id === selectedAppId ? { ...a, days_since_contact: 0, ghosting_risk_score: 10, status_health: 'Healthy' } : a));

    const newComm = {
      id: `comm_${Date.now()}`,
      application_id: selectedAppId,
      sender_type: "candidate",
      date: new Date().toISOString().split('T')[0],
      raw_text: `Sent follow-up: ${draft.subject_line}\n\n${draft.body}`,
