// PLAN:
// 1. Setup: Define NU brand CSS variables and inject via <style>. Load Google Fonts.
// 2. Seed Data: Create realistic applications (Stripe, Vercel, Airbnb) and communications.
// 3. State Management: Main App component holds `currentScreen`, `applications`, `communications`, `selectedAppId`, `draftStrategy`.
// 4. AI Helpers:
//    - `analyzeRisk` (Anthropic): Evaluates timeline for ghosting risk.
//    - `generateDrafts` (Gemini): Creates 3 follow-up options based on strategy.
//    - `decodeEmail` (OpenAI): Extracts intent and tasks from pasted text.
// 5. Components:
//    - `Header`: NU branded top nav.
//    - `DashboardView`: Grid of active applications.
//    - `ApplicationDetailView`: Timeline, Risk Indicator, actions.
//    - `DraftStrategyModal`: Overlay to pick follow-up tone.
//    - `DraftComparisonView`: Side-by-side AI generated drafts with staggered text reveal and spatial expansion.
//    - `LogCommunicationView`: Slide-in panel to paste and decode recruiter emails.
//    - `GhostingRiskIndicator`: Animated SVG donut chart with hover tooltip.
//    - `DemoControls`: Top-right utility for reviewers.
// 6. Motion: framer-motion for screen transitions, panel slides, and staggered list reveals.

const SEED_APPLICATIONS = [
  { id: "app_1", company_name: "Stripe", role_title: "Senior Product Designer", current_stage: "Onsite Panel", days_since_contact: 9, ghosting_risk_score: 88, status_health: "High Risk" },
  { id: "app_2", company_name: "Vercel", role_title: "Frontend Engineer", current_stage: "Hiring Manager Screen", days_since_contact: 2, ghosting_risk_score: 12, status_health: "Healthy" },
  { id: "app_3", company_name: "Airbnb", role_title: "UX Researcher", current_stage: "Take-home Assignment", days_since_contact: 5, ghosting_risk_score: 45, status_health: "Monitor" }
];

const SEED_COMMUNICATIONS = [
  { id: "comm_1", application_id: "app_1", sender_type: "recruiter", date: "2023-10-12", raw_text: "Hi Alex, great having you onsite. We are currently finalizing some headcount planning for Q4. I'll circle back when I have an update.", ai_intent: "delaying for headcount", ai_sentiment: "neutral/ambiguous" },
  { id: "comm_2", application_id: "app_2", sender_type: "recruiter", date: "2023-10-19", raw_text: "Alex! The team loved your background. Let's get you scheduled with the HM next week. Are you free Tuesday?", ai_intent: "genuine interest", ai_sentiment: "highly positive" }
];

// --- AI Helpers ---

async function analyzeRisk(app, comms) {
  const lastComm = comms.filter(c => c.application_id === app.id).pop();
  const prompt = `Company: ${app.company_name}. Stage: ${app.current_stage}. Days since contact: ${app.days_since_contact}. Last email from recruiter: '${lastComm?.raw_text || 'None'}'. Industry avg response: 4 days. Calculate risk. Return ONLY valid JSON with keys: ghosting_risk_score (0-100), status_health ("Healthy", "Monitor", "High Risk"), sentiment_analysis (string), recommended_action (string).`;

  try {
    const res = await fetch('/api/ai/anthropic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: "claude-opus-4-6",
        max_tokens: 500,
        messages: [
          { role: "system", content: "You are an expert technical recruiter and career coach. Analyze the provided timeline and last communication to assess the likelihood the candidate is being ghosted. Output strictly JSON." },
          { role: "user", content: prompt }
        ]
      })
    });
    const data = await res.json();
    const text = data?.content?.[0]?.text || "{}";
    const jsonStr = text.substring(text.indexOf('{'), text.lastIndexOf('}') + 1);
    return JSON.parse(jsonStr);
  } catch (e) {
    console.error("Risk analysis failed", e);
    return { ghosting_risk_score: 75, status_health: "High Risk", sentiment_analysis: "Analysis failed. Assuming high risk due to time elapsed.", recommended_action: "Follow up immediately." };
  }
}

async function generateDrafts(app, comms, strategy) {
  const lastComm = comms.filter(c => c.application_id === app.id).pop();
  const prompt = `Role: ${app.role_title} at ${app.company_name}. Last contact: ${app.days_since_contact} days ago. Last recruiter email: '${lastComm?.raw_text || 'None'}'. Strategy requested: ${strategy}. Generate 3 distinct drafts. Return ONLY valid JSON with a 'drafts' array containing objects with 'id', 'theme', 'subject_line', and 'body'.`;

  try {
    const res = await fetch('/api/ai/gemini-compat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: JSON.stringify({
        model: "gemini-3.1-pro-preview",
        temperature: 0.7,
        max_tokens: 1500,
        messages: [
          { role: "system", content: "You are an executive communication coach. Write highly professional, concise, and context-aware follow-up emails for a job seeker. Never sound desperate. Output strictly JSON." },
          { role: "user", content: prompt }
        ]
      })
    });
    const data = await res.json();
    let text = data?.choices?.[0]?.message?.content || "{}";
    text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '');
    const jsonStr = text.substring(text.indexOf('{'), text.lastIndexOf('}') + 1);
    return JSON.parse(jsonStr).drafts || [];
  } catch (e) {
    console.error("Draft generation failed", e);
    return [
      { id: "1", theme: "Fallback 1", subject_line: "Checking in", body: "Hi, just checking in on the status of my application." },
      { id: "2", theme: "Fallback 2", subject_line: "Following up", body: "Hello, I wanted to follow up regarding the next steps." },
      { id: "3", theme: "Fallback 3", subject_line: "Update request", body: "Hi team, any updates on the role?" }
    ];
  }
}

async function decodeEmail(text) {
  try {
    const res = await fetch('/api/ai/openai', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: JSON.stringify({
        model: "gpt-5.5",
        temperature: 0.2,
        messages: [
          { role: "system", content: "You are an expert at decoding corporate HR speak. Read the raw recruiter email and extract the true intent, sentiment, and any hidden action items. Return ONLY valid JSON with keys: true_intent (string), sentiment (string), next_action_date (string or null), extracted_tasks (array of strings)." },
          { role: "user", content: `Extract data from this recruiter email: '${text}'` }
        ]
      })
    });
    const data = await res.json();
    let content = data?.choices?.[0]?.message?.content || "{}";
    content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
    const jsonStr = content.substring(content.indexOf('{'), content.lastIndexOf('}') + 1);
    return JSON.parse(jsonStr);
  } catch (e) {
    console.error("Decode failed", e);
    return { true_intent: "Unknown", sentiment: "Neutral", next_action_date: null, extracted_tasks: [] };
  }
}

// --- Components ---

const GhostingRiskIndicator = ({ score, status, isLoading, daysSinceContact }) => {
  const radius = 36;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (score / 100) * circumference;

  let color = 'var(--success)';
  if (score >= 75) color = 'var(--friction)';
  else if (score >= 40) color = 'var(--warning)';

  return (
    <div className="risk-indicator-container">
      <div className="risk-donut">
        <svg width="88" height="88" viewBox="0 0 88 88">
          <circle cx="44" cy="44" r={radius} fill="none" stroke="var(--panel)" strokeWidth="8" />
          {!isLoading && (
            <motion.circle
              cx="44" cy="44" r={radius} fill="none"
              stroke={color} strokeWidth="8"
              strokeLinecap="round"
              strokeDasharray={circumference}
              initial={{ strokeDashoffset: circumference, stroke: 'var(--panel)' }}
              animate={{ strokeDashoffset, stroke: color }}
              transition={{ duration: 1.5, ease: "easeOut" }}
              style={{ transformOrigin: 'center', transform: 'rotate(-90deg)' }}
            />
          )}
        </svg>
        <div className="risk-score-center">
          {isLoading ? (
            <div className="shimmer-text" style={{ width: '24px', height: '24px' }} />
          ) : (
            <span className="display-font" style={{ fontSize: '24px', color: 'var(--text-primary)' }}>{score}</span>
          )}
        </div>
        <div className="risk-tooltip">
          {daysSinceContact} days since last contact. Industry avg: 4 days.
        </div>
      </div>
      <div className="risk-meta">
        <div className="label-font" style={{ color: 'var(--text-secondary)' }}>Ghosting Risk</div>
        <div className="body-font" style={{ fontSize: '14px', color, fontWeight: 600 }}>{isLoading ? 'Analyzing...' : status}</div>
      </div>
    </div>
  );
};

const Header = () => (
  <header className="nu-header">
    <div className="nu-logo">Northeastern University</div>
    <div className="app-title">Application Tracker</div>
    <div className="header-actions">
      <div className="avatar">A</div>
    </div>
  </header>
);

const DashboardView = ({ applications, onSelectApp }) => {
  return (
    <motion.div 
