            <div className="card-footer">
              <div className="stage-badge">{app.current_stage}</div>
              <div className="risk-pill" style={{ 
                color: app.ghosting_risk_score > 75 ? 'var(--friction)' : app.ghosting_risk_score > 40 ? 'var(--warning)' : 'var(--success)',
