const DraftComparisonView = ({ app, comms, strategy, onCopy, onCancel }) => {
  const [drafts, setDrafts] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [copiedId, setCopiedId] = useState(null);

  useEffect(() => {
    generateDrafts(app, comms, strategy).then(res => {
      setDrafts(res);
      setIsLoading(false);
    });
  }, [app, comms, strategy]);

  const handleCopy = (draft) => {
    setCopiedId(draft.id);
    setTimeout(() => onCopy(draft), 1500);
  };

  return (
    <motion.div 
      className="screen-container wide-comparison"
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
    >
      <div className="comparison-header">
        <div>
          <h1 className="display-font" style={{ fontSize: '32px', margin: '0 0 8px 0' }}>Review Drafts</h1>
          <div className="body-font" style={{ color: 'var(--text-secondary)' }}>Strategy: {strategy}</div>
        </div>
        <button className="btn-ghost" onClick={onCancel}>Cancel</button>
      </div>

      <motion.div 
        className="drafts-grid"
        initial={{ width: '33%', margin: '0 auto', opacity: 0 }}
        animate={{ width: '100%', opacity: 1 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      >
        {isLoading ? (
          [1, 2, 3].map(i => (
            <div key={i} className="draft-card loading">
              <div className="skeleton-line" style={{ width: '60%', marginBottom: '24px' }} />
              <div className="skeleton-line" />
              <div className="skeleton-line" />
              <div className="skeleton-line" style={{ width: '80%' }} />
            </div>
          ))
        ) : (
          drafts.map((draft, i) => (
            <motion.div 
              key={draft.id} className="draft-card"
              initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.15 + 0.5 }}
            >
              <div className="draft-theme label-font">{draft.theme}</div>
              <div className="draft-subject data-font">Subj: {draft.subject_line}</div>
              <div className="draft-body body-font">
                {draft.body.split('\n').map((paragraph, pIdx) => (
                  <motion.p 
                    key={pIdx}
                    initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: (i * 0.15) + (pIdx * 0.2) + 0.8 }}
                  >
                    {paragraph}
                  </motion.p>
                ))}
              </div>
              <div className="draft-actions">
                <button 
                  className={`btn-secondary ${copiedId === draft.id ? 'success-state' : ''}`} 
                  style={{ width: '100%' }}
                  onClick={() => handleCopy(draft)}
                >
                  {copiedId === draft.id ? <><lucide.Check size={16} /> Copied & Logged</> : 'Copy to Clipboard'}
                </button>
              </div>
            </motion.div>
          ))
        )}
      </motion.div>
    </motion.div>
  );
};

const LogCommunicationPanel = ({ onLog, onClose }) => {
  const [text, setText] = useState('');
  const [isDecoding, setIsDecoding] = useState(false);

  const handleDecode = async () => {
    if (!text.trim()) return;
    setIsDecoding(true);
    const result = await decodeEmail(text);
    setIsDecoding(false);
    onLog(text, result);
  };

  return (
    <div className="panel-overlay" onClick={onClose}>
      <motion.div 
        className="side-panel"
        initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }}
        transition={{ type: 'spring', damping: 25, stiffness: 200 }}
        onClick={e => e.stopPropagation()}
      >
        <div className="panel-header">
          <h2 className="display-font" style={{ fontSize: '24px', margin: 0 }}>Log Communication</h2>
          <button className="btn-icon" onClick={onClose} aria-label="Close Panel"><lucide.X size={24} /></button>
        </div>
        <div className="panel-body">
          <p className="body-font" style={{ color: 'var(--text-secondary)', marginBottom: '16px' }}>
