          </p>
          <textarea 
            className="nu-textarea body-font" 
            placeholder="Paste email text here..."
            value={text}
            onChange={e => setText(e.target.value)}
          />
        </div>
        <div className="panel-footer">
          <button className="btn-primary" style={{ width: '100%' }} onClick={handleDecode} disabled={isDecoding || !text.trim()}>
            {isDecoding ? 'Decoding...' : 'Decode & Log'}
