    setCurrentScreen('draft_comparison_view');
  };

  const handleCopyDraft = (draft) => {
    setApplications(apps => apps.map(a => a.id === selectedAppId ? { ...a, days_since_contact: 0, ghosting_risk_score: 10, status_health: 'Healthy' } : a));

    const newComm = {
      id: `comm_${Date.now()}`,
      application_id: selectedAppId,
      sender_type: "candidate",
      date: new Date().toISOString().split('T')[0],
      raw_text: `Sent follow-up: ${draft.subject_line}\n\n${draft.body}`,
      ai_intent: "proactive follow-up",
      ai_sentiment: "positive"
    };
    setCommunications(prev => [...prev, newComm]);

    setCurrentScreen('application_detail_view');
  };

  const handleLogCommunication = (text, aiResult) => {
    const newComm = {
      id: `comm_${Date.now()}`,
      application_id: selectedAppId,
      sender_type: "recruiter",
      date: new Date().toISOString().split('T')[0],
      raw_text: text,
      ai_intent: aiResult.true_intent,
      ai_sentiment: aiResult.sentiment
    };
    setCommunications(prev => [...prev, newComm]);

    setApplications(apps => apps.map(a => a.id === selectedAppId ? { ...a, days_since_contact: 0, ghosting_risk_score: aiResult.sentiment.includes('positive') ? 20 : 50 } : a));

    setShowLogPanel(false);
  };

  const activeApp = applications.find(a => a.id === selectedAppId) || applications[0];
  const noop = () => {};

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <DemoControls setScreen={setCurrentScreen} />

      <main style={{ flexGrow: 1, position: 'relative' }}>
        <AnimatePresence mode="wait">
          {currentScreen === 'dashboard_view' && (
            <DashboardView key="dash" applications={applications} onSelectApp={handleSelectApp} />
          )}

          {currentScreen === 'application_detail_view' && (
            <ApplicationDetailView 
              key="detail" 
              app={activeApp} 
              comms={communications}
              onBack={() => setCurrentScreen('dashboard_view')}
              onDraftClick={() => setCurrentScreen('draft_strategy_modal')}
              onLogClick={() => setShowLogPanel(true)}
            />
          )}

          {currentScreen === 'draft_strategy_modal' && (
            <ApplicationDetailView 
              key="detail-bg" 
              app={activeApp} 
              comms={communications}
              onBack={noop} onDraftClick={noop} onLogClick={noop}
            />
          )}

          {currentScreen === 'draft_comparison_view' && (
            <DraftComparisonView 
              key="compare"
              app={activeApp}
              comms={communications}
              strategy={draftStrategy}
              onCopy={handleCopyDraft}
              onCancel={() => setCurrentScreen('application_detail_view')}
            />
          )}
        </AnimatePresence>

        <AnimatePresence>
          {currentScreen === 'draft_strategy_modal' && (
            <DraftStrategyModal 
              key="modal"
              onGenerate={handleGenerateDrafts}
              onCancel={() => setCurrentScreen('application_detail_view')}
            />
          )}

          {showLogPanel && (
            <LogCommunicationPanel 
              key="panel"
              onLog={handleLogCommunication}
              onClose={() => setShowLogPanel(false)}
            />
          )}
        </AnimatePresence>
      </main>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
